// Vidéo longue quotidienne Impacteur Afrique : candidats = vidéos repérées par VEILLE AFRIQUE depuis 30 h
const now = Date.now();
const vids = $('Lire vidéos').first().json.data || [];
const src = Object.fromEntries(($('Lire sources').first().json.data || []).map(s => [s.channel_id, s]));
const pubs = ($('Lire publications').first().json.data || []).filter(p => p.compte === 'afrique');
const segsOf = p => { try { const j = JSON.parse(p.segments || '[]'); return Array.isArray(j) ? j : (j.segments || []); } catch (e) { return []; } };
const deja = new Set(pubs.filter(p => p.type === 'longue_afrique').flatMap(p => segsOf(p).map(x => x.video_id)));
let c = vids.filter(v => {
  const s = src[v.channel_id];
  return s && v.compte === 'afrique' && ['afrique','mixte'].includes(s.compte) && s.statut === 'usable' && v.publiee_le && now - Date.parse(v.publiee_le) < 30 * 3600e3
    && !['pas_interessant', 'source_ignoree', 'refus_langue'].includes(v.decision) && !deja.has(v.video_id) && (v.duree_s || 0) >= 20;
}).map(v => ({ ...v, prio: (v.score || 0) + Math.min(2, Math.log10(1 + (v.vues || 0)) / 3) }));
c.sort((a, b) => b.prio - a.prio);
const parSrc = {}; const out = [];
for (const v of c) { parSrc[v.channel_id] = (parSrc[v.channel_id] || 0) + 1; if (parSrc[v.channel_id] > 3) continue; out.push(v); if (out.length >= 14) break; }
if (out.length < 3) throw new Error(`Impacteur Afrique : pas assez de matière pour la vidéo longue (${out.length} vidéos sur 30 h)`);
return out.map(v => ({ json: { video_id: v.video_id, titre: v.titre, source_nom: v.source_nom, channel_id: v.channel_id,
  categorie: src[v.channel_id].categorie, score: v.score, vues: v.vues, decision: v.decision || '', angle: v.angle || '', duree_s: v.duree_s,
  extrait_debut: v.extrait_debut, extrait_fin: v.extrait_fin, personnes: v.personnes || '', camp: v.camp || '', theme: v.theme || '', type_moment: v.type_moment || '' } }));

const cands = $('Choisir les candidats').all();
const out = [];
$input.all().forEach((it, i) => {
  const c = cands[i].json; const ph = it.json.phrases || [];
  if (!ph.length) return;
  let txt = ph.map(p => `[${p.start}-${p.end}|c${p.conf ?? '?'}] ${p.texte}`).join('\n');
  if (txt.length > 45000) txt = txt.slice(0, 45000) + '\n[…transcription tronquée]';
  const system = `Tu es monteur pour « Impacteur Afrique », chaîne YouTube qui publie chaque soir à 20h une vidéo longue sur l'actualité africaine, en français. Objectif : le maximum de vues.
Dans la transcription horodatée ci-dessous (cX = confiance de la transcription française), repère :
1. « court » : LE meilleur passage de 1 min 30 à 4 min (clash, punchline, discours fort, aveu, chiffre choc, émotion, analyse forte) : pour une vidéo longue, le spectateur veut comprendre et suivre un échange complet, pas un flash. Prends le contexte, la montée en tension et la réponse ;
2. « long » : s'il existe, LE meilleur passage continu de 5 à 15 minutes qui se suffit à lui-même (discours marquant, interview percutante, débat tendu, démonstration d'un intellectuel). Sinon null.
RÈGLES : chaque passage commence au début d'une phrase et finit à la fin d'une phrase (horodatages fournis) ; il doit être ENTIÈREMENT EN FRANÇAIS — aucune phrase en wolof, bambara, lingala, dioula, anglais… (texte incohérent ou confiance < c0.80 = suspect) ; compréhensible seul.
Pour chacun : titre de chapitre (≤ 6 mots, factuel), contexte neutre (≤ 15 mots), interet (0-10, potentiel de vues), risque_demonetisation (0-10 : violence, sexualité, accusations non établies, grossièretés, tragédie).
Réponds UNIQUEMENT en JSON : {"court":{"start":0,"end":0,"titre":"...","contexte":"...","interet":0,"risque_demonetisation":0,"raison":"..."},"long":null,"sujet":"...","personnes":"..."}`;
  out.push({ json: { cand: c, phrases: ph, body: { model: 'claude-sonnet-4-5', max_tokens: 900, system,
    messages: [{ role: 'user', content: `Vidéo : ${c.titre}\nSource : ${c.source_nom} (${c.categorie})\nVues : ${c.vues || '?'}\n\nTranscription :\n${txt}` }] } } });
});
if (out.length < 3) throw new Error(`Impacteur Afrique : seulement ${out.length} vidéos transcrites, vidéo longue annulée`);
return out;

const preps = $('Préparer les moments').all();
const res = [];
const confOf = (ph, a, b) => { const x = ph.filter(p => p.start >= a - 0.5 && p.end <= b + 0.5 && p.conf != null); const n = x.reduce((s, p) => s + p.texte.split(' ').length, 0); return n ? x.reduce((s, p) => s + p.conf * p.texte.split(' ').length, 0) / n : 1; };
$input.all().forEach((it, i) => {
  const c = preps[i].json.cand, ph = preps[i].json.phrases || [];
  const txt = (it.json.content || []).map(x => x.text || '').join('');
  let m; try { m = JSON.parse(txt.slice(txt.indexOf('{'), txt.lastIndexOf('}') + 1)); } catch (e) { return; }
  const add = (x, type, min, max) => { if (!x) return; const d = x.end - x.start; if (!(d >= min && d <= max)) return; if (confOf(ph, x.start, x.end) < 0.8) return;
    res.push({ id: res.length, type, video_id: c.video_id, source: c.source_nom, categorie: c.categorie, score_veille: c.score, vues: c.vues, titre_video: c.titre,
      personnes: m.personnes || c.personnes, sujet: m.sujet || '', camp: c.camp, theme: c.theme, type_moment: c.type_moment, start: +x.start, end: +x.end, duree: Math.round(d),
      titre: x.titre, contexte: x.contexte, interet: x.interet, risque_demonetisation: x.risque_demonetisation, raison: x.raison }); };
  add(m.court, 'court', 60, 270); add(m.long, 'long', 270, 960);
});
if (!res.length) throw new Error('Impacteur Afrique : aucun moment exploitable en français');
const d = new Date();
const dateLabel = d.toLocaleDateString('fr-FR', { day: 'numeric', month: 'long', timeZone: 'Europe/Paris' });
const system = `Tu es le rédacteur en chef d'« Impacteur Afrique », chaîne YouTube et Facebook sur l'actualité africaine en français. Chaque soir à 20h, une vidéo longue.
OBJECTIF N°1 : LE MAXIMUM DE VUES (clic + rétention), sans strike ni démonétisation.
PLUS-VALUE ÉDITORIALE : une vidéo longue n'est pas une suite de flashs. Le spectateur doit ressortir en ayant compris un sujet : donne un fil rouge à la vidéo (un thème ou une question qui relie les extraits), ordonne les extraits pour raconter une histoire, ; la plus-value vient du choix et de l'ordre des extraits et des titres à l'écran, pas d'une voix off bavarde.
Choisis le FORMAT du jour selon la matière disponible (passages « court » de 1 min 30-4 min et passages « long » de 5-15 min) :
- « zapping » : 3 à 6 passages de 1 min 30 à 4 min chacun (total des extraits 8 à 15 min) ; pour une vidéo longue, privilégie des échanges complets qu'on comprend, jamais des flashs de quelques secondes, le meilleur de l'actualité africaine du jour ; ouvre sur le plus fort, enchaîne par thèmes, garde un moment fort pour la fin ;
- « extrait_long » : UN passage long exceptionnel (discours, interview, débat) qui fera plus de vues seul qu'un zapping ; tu peux le raccourcir, jamais l'allonger ;
- « confrontation » : 2 ou 3 passages (2 à 5 min chacun) de vidéos DIFFÉRENTES qui se répondent sur un même sujet (points de vue opposés) ; total 4 à 12 min.
Règles : écarte tout moment avec risque_demonetisation ≥ 6 ; au plus 2 extraits par chaîne en zapping ; tu peux raccourcir un passage (ajuste start/end) mais jamais l'allonger ; reste neutre (montre, ne prends pas parti).
VOIX OFF : le public a très peu d'attention, la voix off doit être LA PLUS COURTE POSSIBLE et ne jamais ennuyer. voix_intro : 1 phrase d'accueil (« Bonsoir, voici Impacteur Afrique. ») + UNE accroche sur le moment le plus fort, 8 s maximum. Pour chaque segment, voix : UNE phrase percutante (15 mots max, ≈ 5 s) qui donne envie de voir la suite : qui parle et l'enjeu, formulés comme une accroche, jamais comme un résumé. Tu peux aller jusqu'à 2 phrases SEULEMENT si tu révèles un contexte que le spectateur ignore et qui rend l'extrait plus fort. Pendant la voix off, les images de l'extrait défilent à l'écran. voix_outro : 1 phrase courte (rendez-vous demain + abonnement). N'affirme que ce qui figure dans les éléments fournis. Écris pour l'oral, phrases vivantes, ponctuation qui donne du rythme.
TITRE YouTube (≤ 95 caractères) — reprends le MODÈLE DE LA CHAÎNE. Ses titres qui ont le mieux marché : « 🇬🇦 GABON : LE PACTE SECRET QUI A PORTÉ OLIGUI AU POUVOIR » (11 000 vues) ; « 🇬🇦 GABON : TOUTE LA VÉRITÉ SUR LA NUIT DU COUP D’ÉTAT » (6 400) ; « 🇬🇦 GABON : POURQUOI OLIGUI A-T-IL FAIT EMPRISONNER SYLVIA ET NOUREDDIN BONGO ? » (1 700) ; « 🇬🇦 GABON : ALI BONGO A-T-IL VOLÉ L’ÉLECTION PRÉSIDENTIELLE DE 2009 ? » (1 300). Ses titres qui n'ont PAS marché : « KABILA détruit Tshisekedi : « Ivan le Terrible ! » + Jeune Malien AGRESSÉ » ; « NARCO-ÉTAT en Sierra Leone : Jos le joufflu RÈGNE sur Freetown » ; « DETTE du Cameroun : les chiffres QUI CHOQUENT + Kidal reprise + CFA démasqué ».
- Forme : emoji drapeau du pays + espace + PAYS EN MAJUSCULES + « : » + UNE seule histoire, tout en MAJUSCULES ; de préférence une question (POURQUOI… ? / X A-T-IL… ? / … OU … ?) ou une révélation (LA VÉRITÉ SUR…, LE PACTE SECRET…, COMMENT X A…).
- UN SEUL sujet : celui du segment qui OUVRE la vidéo (mets en premier le passage le plus fort). Jamais de « + », jamais deux sujets, jamais de citation entre guillemets.
- Nomme une personnalité CONNUE du public africain (chef d'État, ministre, opposant, chef de junte…) au cœur du sujet, même si elle ne parle pas dans l'extrait. INTERDIT : surnoms, sobriquets, personnes que le grand public ne connaît pas (si le passage parle d'un inconnu, désigne-le par son rôle : « UN BARON DE LA DROGUE »).
- Noms propres : orthographe officielle. La transcription automatique déforme les noms (ex. « Malade Biot » = Julius Maada Bio) : vérifie avec titre_video et tes connaissances ; en cas de doute, n'utilise pas le nom.
- Jamais mensonger : la question doit être réellement traitée dans l'extrait ; aucune accusation présentée comme un fait, aucune insulte.
accroche ≤ 60 caractères ; description 2-3 phrases ; 8 à 12 tags (dont Afrique et les pays concernés).
MINIATURE — elle doit RACONTER L'HISTOIRE en une image et créer de la TENSION, comme les meilleures miniatures de la chaîne (ex. Oligui au premier plan, les Bongo derrière des barreaux, le palais présidentiel sous l'orage). Une miniature molle = pas de clic.
- pays = nom du pays ; drapeau = code ISO 3166-1 alpha-2 en minuscules (ga, cd, sn, ml, cm, sl…).
- personnages = 1 à 3 personnalités CONNUES de l'histoire (leurs photos sont cherchées sur Wikipédia/Wikimedia) : [{"nom":"nom officiel complet","wiki":"titre exact de la page Wikipédia française","role":"principal|secondaire","effet":"aucun|barreaux|rouge|sombre","etiquette":"2-3 mots en majuscules ou vide"}]. Un seul « principal » (celui dont parle le titre). Mets les DEUX camps quand il y a un affrontement (ex. Kabila ET Tshisekedi).
  effet « barreaux » UNIQUEMENT si la personne est réellement détenue, emprisonnée ou poursuivie ; « rouge » pour la personne accusée / l'adversaire désigné dans l'extrait ; « sombre » pour un disparu ou un pouvoir déchu ; sinon « aucun ».
  RÈGLE DE SÉCURITÉ : ne montre JAMAIS le visage d'une personne à côté d'une accusation (drogue, corruption, crime…) qui vise quelqu'un d'autre : le spectateur croirait que c'est elle. Si l'accusé n'est pas une personnalité connue avec une photo, ne mets que des personnes qui ne peuvent pas être confondues avec lui, ou aucune.
  etiquette = qui est-ce, en 2-3 mots (« SYLVIA BONGO », « EX-PRÉSIDENT ») si le visage n'est pas connu de tous ; sinon vide.
- eclair = true quand l'histoire est un CONFLIT, une rupture, une rivalité ou une trahison entre personnes (des éclairs zébreront l'image entre elles) ; false sinon.
- chiffre = chiffre ou mot choc en pastille rouge (≤ 12 caractères : « 30 M€ », « 16 MOIS », « NARCO-ÉTAT ») s'il est dans l'extrait ; sinon vide.
- montrer_invite = true seulement si l'intervenant du segment d'ouverture est lui-même connu (opposant, expert reconnu) et qu'il reste de la place (moins de 3 personnages) ; invite_etiquette = son nom en majuscules.
- vedette = id du segment d'OUVERTURE (le sujet du titre).
- ACCUSATIONS : n'affirme JAMAIS qu'une personne ment, vole, est corrompue, coupable ou criminelle. Si l'extrait contient une accusation, présente-la comme une question (« NUÑEZ A-T-IL MINIMISÉ… ? ») ou comme une citation attribuée à celui qui la porte (« X ACCUSE Y DE… »). N'attribue une fonction (étiquette « MINISTRE »…) que si elle est actuelle et exacte, et ne mets en avant (effet « rouge ») que la personne réellement mise en cause dans l'extrait.
- TEST DU SPECTATEUR : quelqu'un qui ne connaît rien à l'affaire et ne voit QUE la miniature doit comprendre DE QUOI on parle (le sujet concret : grenades de la police, retraites, lycéens, prison, élection…) et QUI est concerné. Le texte de la miniature nomme toujours le SUJET CONCRET. INTERDIT : les textes « mystère » ou elliptiques qui n'ont de sens qu'après avoir vu l'extrait (MAUVAIS : « UNE SUSPENDUE, QUATRE MAINTENUES », « JOS RÈGNE », « DETTE X6 » ; BONS : « GRENADES DE LA POLICE : *TOUJOURS AUTORISÉES ?* », « ZELENSKY *NE DEVRAIT PLUS* ÊTRE PRÉSIDENT », « POURQUOI OLIGUI A EMPRISONNÉ LES BONGO ? »).
- miniature_texte = 3 à 7 mots en français qui se comprennent SEULS : question ou révélation (« POURQUOI OLIGUI A EMPRISONNÉ LES BONGO ? », « ALI BONGO : ÉLU OU PUTSCHISTE ? », « LE PUTSCH, HEURE PAR HEURE ») ; 1 à 3 mots clés entre *astérisques* (en jaune) ; jamais un mot isolé incompréhensible (INTERDIT : « JOS RÈGNE », « DETTE X6 »).
- decor_prompt = en anglais, un DÉCOR QUI RACONTE L'HISTOIRE, très dramatique et détaillé, avec des SYMBOLES fidèles aux faits de l'extrait, au premier plan et en fond : pouvoir (palais présidentiel, trône, fauteuil vide), justice (porte de cellule, menottes, marteau de juge), richesse et corruption (lingots d'or, diamants bruts, liasses de billets, valises d'argent), guerre (villages en flammes, colonnes de fumée, blindés au loin), coup d'État (chars devant le palais, nuit, gyrophares), drogue (paquets de cocaïne sur un quai), révolte (foule en colère, pneus brûlés), pétrole/mines (puits en feu, coltan), orage et éclairs pour la tension ; lieu réel du pays, couleurs du drapeau, éclairage cinéma contrasté (orange feu / bleu nuit). SANS personne visible, sans texte, sans sang. N'utilise un symbole que s'il correspond à l'histoire (pas de guerre s'il n'y a pas de conflit armé).
Réponds UNIQUEMENT en JSON :
{"format":"zapping|extrait_long|confrontation","pourquoi":"...","titre":"...","accroche":"...","description":"...","tags":["..."],"voix_intro":"...","voix_outro":"...","vedette":0,"montrer_invite":false,"invite_etiquette":"","pays":"...","drapeau":"..","personnages":[{"nom":"...","wiki":"...","role":"principal","effet":"aucun","etiquette":""}],"eclair":false,"chiffre":"","miniature_texte":"...","decor_prompt":"...","segments":[{"id":0,"start":0,"end":0,"titre":"...","contexte":"...","voix":"..."}]}`;
return [{ json: { moments: res, dateLabel, body: { model: 'claude-sonnet-4-5', max_tokens: 6000, system, messages: [{ role: 'user', content: JSON.stringify(res) }] } } }];

const prev = $('Rédaction').first().json;
const byId = Object.fromEntries(prev.moments.map(m => [m.id, m]));
const txt = ($input.first().json.content || []).map(x => x.text || '').join('');
const r = JSON.parse(txt.slice(txt.indexOf('{'), txt.lastIndexOf('}') + 1));
const segs = [];
for (const s of r.segments || []) {
  const m = byId[s.id]; if (!m) continue;
  let a = Math.max(m.start, +s.start || m.start), b = Math.min(m.end, +s.end || m.end);
  if (b - a < 10) { a = m.start; b = m.end; }
  segs.push({ video_id: m.video_id, start: a, end: b, id_moment: s.id, titre: s.titre || m.titre, contexte: s.contexte || m.contexte, voix: String(s.voix || '').slice(0, 260), source: m.source, categorie: m.categorie, personnes: m.personnes, camp: m.camp, theme: m.theme, type_moment: m.type_moment });
}
const format = ['zapping','extrait_long','confrontation'].includes(r.format) ? r.format : 'zapping';
if (segs.length < (format === 'zapping' ? 3 : 1)) throw new Error('Impacteur Afrique : conducteur trop court (' + segs.length + ' extraits)');
const totalS = segs.reduce((t, s) => t + (s.end - s.start), 0);
if (totalS < 300) throw new Error(`Impacteur Afrique : pas assez de matière ce soir (${Math.round(totalS)} s d'extraits, minimum 5 min) — pas de vidéo longue aujourd'hui`);
const total = segs.reduce((t, s) => t + (s.end - s.start), 0);
const ymd = new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Paris' });
const nom = 'afr_' + ymd.replace(/-/g, '');
// heure de publication : 20h Paris aujourd'hui (ou tout de suite si déjà passé)
const offs = new Date().toLocaleString('en-US', { timeZone: 'Europe/Paris', timeZoneName: 'shortOffset' }).match(/GMT([+-]\d+)/);
const h = offs ? parseInt(offs[1]) : 2;
let pub = new Date(`${ymd}T20:00:00${h >= 0 ? '+' : '-'}${String(Math.abs(h)).padStart(2, '0')}:00`);
if (pub.getTime() < Date.now() + 60e3) pub = new Date(Date.now() + 60e3);
return [{ json: { nom, ymd, dateLabel: prev.dateLabel, titre: r.titre, accroche: r.accroche, description: r.description, tags: r.tags || [], hypothese: (format + ' — ' + (r.pourquoi || '')).slice(0, 300), format,
  segments: segs, total_extraits_s: Math.round(total), publier_a: pub.toISOString(),
  voix_intro: r.voix_intro || '', voix_outro: r.voix_outro || '',
  requete: { nom, date_label: prev.dateLabel, marque: 'IMPACTEUR AFRIQUE', intro_rouge: ({ zapping: `L'actualité africaine du ${prev.dateLabel}`, extrait_long: 'Le moment fort du jour', confrontation: 'Face à face' })[format], bandeau_miniature: '', outro_gros: 'À DEMAIN, 20H', outro_rouge: 'Abonne-toi pour ne rien rater', outro_petit: 'Impacteur Afrique — l’actualité africaine en français', accroche: r.accroche, miniature_texte: String(r.miniature_texte || '').slice(0, 80), decor_prompt: String(r.decor_prompt || '').slice(0, 500), vedette: Math.max(0, segs.findIndex(s => Number(s.id_moment) === Number(r.vedette))), style: 'afrique', personnages: (Array.isArray(r.personnages) ? r.personnages : []).slice(0, 3).map(p => ({ nom: String(p.nom || '').slice(0, 80), wiki: String(p.wiki || '').slice(0, 120), role: p.role === 'principal' ? 'principal' : 'secondaire', effet: ['barreaux','rouge','sombre'].includes(p.effet) ? p.effet : 'aucun', etiquette: String(p.etiquette || '').slice(0, 40) })), personnalite: String(((r.personnages || []).find(p => p.role === 'principal') || (r.personnages || [])[0] || {}).nom || r.personnalite || '').slice(0, 80), personnalite_wiki: '', eclair: !!r.eclair, chiffre: String(r.chiffre || '').slice(0, 14), invite_etiquette: String(r.invite_etiquette || '').slice(0, 40), drapeau: String(r.drapeau || '').toLowerCase().slice(0, 2), montrer_invite: !!r.montrer_invite && segs.findIndex(s => Number(s.id_moment) === Number(r.vedette)) === 0, pays: String(r.pays || ''), voix_intro: String(r.voix_intro || '').slice(0, 600), voix_outro: String(r.voix_outro || '').slice(0, 300), segments: segs.map(({ video_id, start, end, titre, contexte, source, voix }) => ({ video_id, start, end, titre, contexte, source, voix })) } } }];

const c = { ...$('Conducteur').first().json, ...$('Appliquer relecture').first().json };
const job = $('État du montage').last().json;
const mmss = t => `${String(Math.floor(t / 60)).padStart(2, '0')}:${String(Math.round(t % 60)).padStart(2, '0')}`;
const chap = ['00:00 Intro', ...(job.chapitres || []).map(ch => `${mmss(ch.t)} ${ch.titre}`)];
const sources = [...new Set(c.segments.map(s => s.source))];
const description = `${c.description}

Au sommaire :
${chap.join('
')}

Sources : ${sources.join(', ')}.${sources.some(s => /s[ée]nat/i.test(s)) ? '
Images fournies par le Sénat français.' : ''}${sources.some(s => /assembl[ée]e nationale/i.test(s)) ? '
Images : Assemblée nationale.' : ''}
Extraits courts cités à des fins d'information et de revue de l'actualité ; tous droits aux ayants droit.${(job.voix && job.voix.generees) ? '
Voix off générée par synthèse vocale.' : ''}

Impacteur Afrique — l'actualité africaine en français, chaque soir à 20h.
#Afrique #actualite #politique`;
return [{ json: { ...c, description_finale: description, fichier: job.fichier, miniature: job.miniature, duree_s: job.duree_s, chapitres: job.chapitres || [], erreurs_montage: job.erreurs || [], miniature_erreurs: job.miniature_erreurs || [], originaux_longs: job.originaux_longs || [], voix: job.voix || {}, sources } }];

const c = $('Description').first().json;
let yt = {}; try { yt = $('Publier sur YouTube').first().json; } catch (e) {}
let fb = {}; try { fb = $('Publier sur Facebook').first().json; } catch (e) {}
let th = {}; try { th = $('Miniature YouTube').first().json; } catch (e) {}
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const m = Math.floor(c.duree_s / 60), s = c.duree_s % 60;
const lignes = [
  `🌍 <b>Impacteur Afrique — vidéo du ${esc(c.dateLabel)} publiée</b> (${esc(c.format)})`, `<b>${esc(c.titre)}</b> · ${m} min ${s} s · ${c.chapitres.length} extraits`, '',
  ...c.chapitres.map((ch, i) => `${i + 1}. ${esc(ch.titre)} <i>(${esc(ch.source)})</i>`), '',
